settings.custom_liquid:
{%- comment -%}
  Product Breadcrumb (localized hardcoded parent + metafield collection)
  Structure:
  [Localized parent] / {{ collection from metafield }} / {{ product.title }}

  - No "Category" label
  - Localized "Rubber fenders" label + locale-aware parent URL
  - Uses product.metafields.custom.collectie (Collection reference)
  - JSON-LD included
{%- endcomment -%}

{%- assign bc_col = product.metafields.custom.collectie.value -%}

{%- assign locale = request.locale.iso_code | downcase -%}
{%- assign parent_title = 'Rubber fenders' -%}
{%- assign parent_url = '/collections/rubber-fenders' -%}

{%- case locale -%}
  {%- when 'de' -%}
    {%- assign parent_title = 'Gummi-Fender' -%}
    {%- assign parent_url = '/collections/gummifender' -%}

  {%- when 'es' -%}
    {%- assign parent_title = 'Defensas de goma' -%}
    {%- assign parent_url = '/collections/defensas-de-goma' -%}

  {%- when 'fr' -%}
    {%- assign parent_title = 'Défenses en caoutchouc' -%}
    {%- assign parent_url = '/collections/defenses-en-caoutchouc' -%}

  {%- when 'it' -%}
    {%- assign parent_title = 'Parabordi in gomma' -%}
    {%- assign parent_url = '/collections/parabordi-in-gomma' -%}

  {%- when 'sv-se' -%}
    {%- assign parent_title = 'Gummifendrar' -%}
    {%- assign parent_url = '/collections/gummi-fender' -%}

  {%- when 'da-dk' -%}
    {%- assign parent_title = 'Gummifendere' -%}
    {%- assign parent_url = '/collections/rubber-fenders' -%}

  {%- when 'no' -%}
    {%- assign parent_title = 'Gummifendere' -%}
    {%- assign parent_url = '/collections/rubber-fenders' -%}

  {%- when 'nl' -%}
    {%- assign parent_title = 'Rubber fenders' -%}
    {%- assign parent_url = '/collections/rubber-fenders' -%}
{%- endcase -%}

{%- if bc_col != blank -%}
  <div class="breadcrumbs-wrap">
    <nav class="breadcrumbs" aria-label="Breadcrumb">
      <ol class="breadcrumbs__list" role="list">

        <!-- Localized parent -->
        <li class="breadcrumbs__item">
          <a class="breadcrumbs__link" href="{{ parent_url }}">
            {{ parent_title }}
          </a>
        </li>

        <li class="breadcrumbs__item" aria-hidden="true">/</li>

        <!-- Metafield collection -->
        <li class="breadcrumbs__item">
          <a class="breadcrumbs__link" href="{{ bc_col.url }}">
            {{ bc_col.title }}
          </a>
        </li>

        <li class="breadcrumbs__item" aria-hidden="true">/</li>

        <!-- Current product -->
        <li class="breadcrumbs__item">
          <span class="breadcrumbs__current" aria-current="page">
            {{ product.title }}
          </span>
        </li>

      </ol>
    </nav>
  </div>

  <script type="application/ld+json">
  {
    "@context": "https://schema.org",
    "@type": "BreadcrumbList",
    "itemListElement": [
      {
        "@type": "ListItem",
        "position": 1,
        "name": {{ parent_title | json }},
        "item": "{{ shop.url }}{{ parent_url }}"
      },
      {
        "@type": "ListItem",
        "position": 2,
        "name": {{ bc_col.title | json }},
        "item": "{{ shop.url }}{{ bc_col.url }}"
      },
      {
        "@type": "ListItem",
        "position": 3,
        "name": {{ product.title | json }},
        "item": "{{ shop.url }}{{ product.url }}"
      }
    ]
  }
  </script>

  <style>
    .breadcrumbs-wrap {
      max-width: 1200px;
      margin: 0 auto;
      padding: 0;
    }

    @media screen and (max-width: 749px) {
      .breadcrumbs-wrap {
        padding-left: 2rem;
        padding-right: 2rem;
      }
    }

    .breadcrumbs {
      margin: 0;
      padding: 0;
      font-family: inherit;
      font-size: 16px;
      font-weight: 400;
      line-height: 1.2;
      color: #BF1E2D;
    }

    .breadcrumbs__list {
      display: flex;
      align-items: center;
      gap: 8px;
      padding: 0;
      margin: 0;
      list-style: none;
      flex-wrap: wrap;
    }

    .breadcrumbs__link {
      color: #BF1E2D;
      text-decoration: none;
    }

    .breadcrumbs__link:hover {
      text-decoration: underline;
    }

    .breadcrumbs__current {
      color: #BF1E2D;
      font-size: 16px;
      font-weight: 400;
    }
  </style>
{%- endif -%}

{% if product.metafields.custom.tabel_html %}
  <div
    class="custom-table-container"
    data-lang="{{ request.locale.iso_code | slice: 0, 2 | downcase }}"
  >
    {{ product.metafields.custom.tabel_html }}
  </div>

  <script defer>
  (function () {
    function norm(s) {
      return (s || "")
        .replace(/\u00A0/g, " ")
        .replace(/\s+/g, " ")
        .trim()
        .toLowerCase();
    }

    var translations = {
      nl: {
        "product name": "Producttitel",
        "weight (kg/m)": "Gewicht (kg/m)",
        "weight (kg / m)": "Gewicht (kg/m)",
        "max length (mm)": "Max. lengte (mm)",
        "top uhmw-pe (mm)": "Bovenlaag UHMW-PE (mm)"
      },
      de: {
        "product name": "Produkttitel",
        "weight (kg/m)": "Gewicht (kg/m)",
        "weight (kg / m)": "Gewicht (kg/m)",
        "max length (mm)": "Max. Länge (mm)",
        "top uhmw-pe (mm)": "UHMW-PE-Deckschicht (mm)"
      },
      es: {
        "product name": "Título del producto",
        "weight (kg/m)": "Peso (kg/m)",
        "weight (kg / m)": "Peso (kg/m)",
        "max length (mm)": "Longitud máx. (mm)",
        "top uhmw-pe (mm)": "Capa superior UHMW-PE (mm)"
      },
      it: {
        "product name": "Titolo del prodotto",
        "weight (kg/m)": "Peso (kg/m)",
        "weight (kg / m)": "Peso (kg/m)",
        "max length (mm)": "Lunghezza max (mm)",
        "top uhmw-pe (mm)": "Strato superiore UHMW-PE (mm)"
      },
      sv: {
        "product name": "Produkttitel",
        "weight (kg/m)": "Vikt (kg/m)",
        "weight (kg / m)": "Vikt (kg/m)",
        "max length (mm)": "Max. längd (mm)",
        "top uhmw-pe (mm)": "Övre UHMW-PE-skikt (mm)"
      },
      da: {
        "product name": "Produkttitel",
        "weight (kg/m)": "Vægt (kg/m)",
        "weight (kg / m)": "Vægt (kg/m)",
        "max length (mm)": "Maks. længde (mm)",
        "top uhmw-pe (mm)": "Øverste UHMW-PE-lag (mm)"
      },
      no: {
        "product name": "Produkttittel",
        "weight (kg/m)": "Vekt (kg/m)",
        "weight (kg / m)": "Vekt (kg/m)",
        "max length (mm)": "Maks. lengde (mm)",
        "top uhmw-pe (mm)": "Øvre UHMW-PE-lag (mm)"
      },
      fr: {
        "product name": "Titre du produit",
        "weight (kg/m)": "Poids (kg/m)",
        "weight (kg / m)": "Poids (kg/m)",
        "max length (mm)": "Longueur max. (mm)",
        "top uhmw-pe (mm)": "Couche supérieure UHMW-PE (mm)"
      }
    };

    document.addEventListener("DOMContentLoaded", function () {
      document
        .querySelectorAll(".custom-table-container[data-lang]")
        .forEach(function (wrap) {
          var lang = wrap.getAttribute("data-lang");
          var map = translations[lang];
          if (!map) return;

          wrap.querySelectorAll("th").forEach(function (th) {
            var key = norm(th.textContent);
            if (map[key]) th.textContent = map[key];
          });
        });
    });
  })();
  </script>
{% endif %}

{%- liquid
  comment
    FenderTec Diagonal Banner (Product)
    - Default content = translated "{{ product.title }} in stock" + 5 USPs (with bold parts)
    - Optional text override via metafield:   product.metafields.custom.text_schuinestreep
    - Optional image override via metafield:  product.metafields.custom.afbeelding_schuinestreep
      (works with file reference OR URL string)

    NOTE:
    - Default image is a fixed URL (as requested).
  endcomment

  assign uid = section.id | append: '-' | append: product.id
  assign uid = uid | replace: '-', '' | replace: '_', '' | replace: ' ', ''

  assign bannerH     = 300
  assign diagTopX    = 75
  assign diagBottomX = 240
  assign foldW       = 26
  assign bandW       = 34
  assign bandTopY    = 84

  assign leftPadX  = 96
  assign rightPadX = 52

  assign delta = diagBottomX | minus: diagTopX
  assign diagAtBandY = delta | times: bandTopY | divided_by: bannerH | plus: diagTopX

  assign mf_html_obj = product.metafields.custom.text_schuinestreep
  assign mf_img_obj  = product.metafields.custom.afbeelding_schuinestreep

  assign lang = localization.language.iso_code | default: 'en'

  comment
    Default image (fixed)
  endcomment
  assign fallback_img_url = 'https://cdn.shopify.com/s/files/1/0916/3535/1901/files/Naamloze_presentatie.jpg?v=1768828532'
  assign img_url = fallback_img_url

  comment
    Optional image override via metafield (file ref or URL string)
  endcomment
  if mf_img_obj != blank and mf_img_obj.value != blank
    if mf_img_obj.value.url != blank
      assign img_url = mf_img_obj.value | image_url: width: 2000
    else
      assign img_url = mf_img_obj.value
    endif
  endif

  comment
    Build translated title + USPs
  endcomment

  assign product_title = product.title | default: 'Product'

  assign title_suffix = 'in stock'
  if lang == 'nl'
    assign title_suffix = 'op voorraad'
  elsif lang == 'de'
    assign title_suffix = 'auf Lager'
  elsif lang == 'fr'
    assign title_suffix = 'en stock'
  elsif lang == 'es'
    assign title_suffix = 'en stock'
  elsif lang == 'it'
    assign title_suffix = 'disponibile'
  elsif lang == 'sv'
    assign title_suffix = 'i lager'
  elsif lang == 'no'
    assign title_suffix = 'på lager'
  endif

  assign default_title = product_title | append: ' ' | append: title_suffix

  comment
    USPs with consistent bold parts
  endcomment

  assign usp1_html = '<strong>Wide range</strong> of rubber fenders &amp; bumpers'
  assign usp2_html = '<strong>Cut &amp; pre-drilled</strong> fenders with short lead times'
  assign usp3_html = '<strong>Custom</strong> fender and bumper designs'
  assign usp4_html = '<strong>Fast</strong> and flexible production'
  assign usp5_html = '<strong>60+ years</strong> of experience in the rubber fender industrie'

  if lang == 'nl'
    assign usp1_html = '<strong>Breed assortiment</strong> rubber fenders &amp; bumpers'
    assign usp2_html = '<strong>Gesneden &amp; voorgeboord</strong> met korte levertijden'
    assign usp3_html = '<strong>Maatwerk</strong> fender- en bumperontwerpen'
    assign usp4_html = '<strong>Snelle</strong> en flexibele productie'
    assign usp5_html = '<strong>60+ jaar</strong> ervaring in rubber fender productie'
  elsif lang == 'de'
    assign usp1_html = '<strong>Große Auswahl</strong> an Gummi-Fendern &amp; Anfahrschutz'
    assign usp2_html = '<strong>Zugeschnitten &amp; vorgebohrt</strong> mit kurzen Lieferzeiten'
    assign usp3_html = '<strong>Kundenspezifische</strong> Konstruktionen'
    assign usp4_html = '<strong>Kurze</strong> und flexible Produktionszeiten'
    assign usp5_html = '<strong>60+ Jahre</strong> Erfahrung in der Gummi-Fenderfertigung'
  elsif lang == 'fr'
    assign usp1_html = '<strong>Large gamme</strong> de defenses en caoutchouc &amp; butoirs'
    assign usp2_html = '<strong>Decoupees &amp; pre-percees</strong> avec des delais courts'
    assign usp3_html = '<strong>Sur mesure</strong> (defenses et butoirs)'
    assign usp4_html = '<strong>Production</strong> rapide et flexible'
    assign usp5_html = "<strong>60+ ans</strong> d&#39;experience dans la fabrication de defenses en caoutchouc"
  elsif lang == 'es'
    assign usp1_html = '<strong>Amplia gama</strong> de defensas de goma &amp; topes'
    assign usp2_html = '<strong>Cortadas &amp; pre-taladradas</strong> con plazos cortos'
    assign usp3_html = '<strong>A medida</strong> (defensas y topes)'
    assign usp4_html = '<strong>Produccion</strong> rapida y flexible'
    assign usp5_html = '<strong>60+ anos</strong> de experiencia en defensas de goma'
  elsif lang == 'it'
    assign usp1_html = '<strong>Ampia gamma</strong> di paracolpi in gomma &amp; bumper'
    assign usp2_html = '<strong>Tagliati &amp; preforati</strong> con tempi rapidi'
    assign usp3_html = '<strong>Su misura</strong> (paracolpi e bumper)'
    assign usp4_html = '<strong>Produzione</strong> rapida e flessibile'
    assign usp5_html = '<strong>60+ anni</strong> di esperienza nella produzione'
  elsif lang == 'sv'
    assign usp1_html = '<strong>Brett sortiment</strong> av gummifendrar &amp; stötfångare'
    assign usp2_html = '<strong>Kapade &amp; förborrade</strong> med korta ledtider'
    assign usp3_html = '<strong>Skräddarsydda</strong> designer'
    assign usp4_html = '<strong>Snabb</strong> och flexibel produktion'
    assign usp5_html = '<strong>60+ år</strong> erfarenhet av tillverkning'
  elsif lang == 'no'
    assign usp1_html = '<strong>Bredt utvalg</strong> av gummifendere &amp; støtfangere'
    assign usp2_html = '<strong>Kappede &amp; forhåndsborede</strong> med korte ledetider'
    assign usp3_html = '<strong>Skreddersydde</strong> design'
    assign usp4_html = '<strong>Rask</strong> og fleksibel produksjon'
    assign usp5_html = '<strong>60+ år</strong> erfaring med produksjon'
  endif

  assign default_html = '<h3>' | append: default_title | append: '</h3>'
  assign default_html = default_html | append: '<ul>'
  assign default_html = default_html | append: '<li>' | append: usp1_html | append: '</li>'
  assign default_html = default_html | append: '<li>' | append: usp2_html | append: '</li>'
  assign default_html = default_html | append: '<li>' | append: usp3_html | append: '</li>'
  assign default_html = default_html | append: '<li>' | append: usp4_html | append: '</li>'
  assign default_html = default_html | append: '<li>' | append: usp5_html | append: '</li>'
  assign default_html = default_html | append: '</ul>'

  assign content_html = default_html
  if mf_html_obj != blank and mf_html_obj.value != blank
    assign content_html = mf_html_obj.value | strip
  endif
-%}
{% if lang == 'en' %}

<style>
  .rt-{{ uid }}{ --bandColor:#BF1E2D; }

  .rt-{{ uid }}.rt-wrap{
    max-width:1200px;
    margin:0 auto;
    border:1px solid #d9d9d9;
    background:#fff;
    overflow:hidden;
  }

  .rt-{{ uid }} .rt-banner{
    display:flex;
    height:{{ bannerH }}px;
  }

  .rt-{{ uid }} .rt-left{
    width:54%;
    padding:24px {{ rightPadX }}px 24px {{ leftPadX }}px;
    box-sizing:border-box;
    display:flex;
    align-items:center;
  }

  .rt-{{ uid }} .rt-left .c{
    max-width:720px;
    width:100%;
  }

  .rt-{{ uid }} .rt-left h3{
    margin:0 0 16px;
    font-size:24px;
    line-height:1.15;
    font-weight:600;
    color:#4b4b4b;
  }

  .rt-{{ uid }} .rt-left ul{
    margin:0;
    padding-left:18px;
  }

  .rt-{{ uid }} .rt-left li{
    margin:8px 0;
    font-size:16px;
    line-height:1.45;
    color:#7a7a7a;
    font-weight:400;
  }

  .rt-{{ uid }} .rt-left li strong{
    font-weight:700;
    color:#4b4b4b;
  }

  .rt-{{ uid }} .rt-right{
    width:46%;
    position:relative;
    background:#fff;
  }

  .rt-{{ uid }} .rt-right svg{
    display:block;
    width:100%;
    height:100%;
  }

  .rt-{{ uid }} .rt-svg-mobile{display:none;}

  @media (max-width: 900px){
    .rt-{{ uid }}.rt-wrap{
      border:none !important;
      background:transparent !important;
      overflow:visible !important;
      padding:0 16px;
      box-sizing:border-box;
    }

    .rt-{{ uid }} .rt-banner{
      flex-direction:column;
      height:auto;
      background:transparent !important;
      border:none !important;
      gap:12px;
    }

    .rt-{{ uid }} .rt-right{
      width:100%;
      height:220px;
      order:1;
      background:transparent !important;
    }

    .rt-{{ uid }} .rt-left{
      width:100%;
      padding:0 !important;
      align-items:flex-start;
      order:2;
    }

    .rt-{{ uid }} .rt-left .c{
      background:#fff;
      padding:16px 16px 18px;
      border:1px solid #e6e6e6;
    }

    .rt-{{ uid }} .rt-svg-desktop{display:none !important;}
    .rt-{{ uid }} .rt-svg-mobile{display:block !important;}
  }
</style>

<div class="rt-wrap rt-{{ uid }}">
  <div class="rt-banner">
    <div class="rt-left">
      <div class="c">
        {{ content_html }}
      </div>
    </div>

    <div class="rt-right">
      <svg class="rt-svg-desktop" viewBox="0 0 700 {{ bannerH }}" preserveAspectRatio="xMidYMid slice" aria-hidden="true"
           xmlns="http://www.w3.org/2000/svg"
           xmlns:xlink="http://www.w3.org/1999/xlink">
        <defs>
          <clipPath id="imgClip-{{ uid }}">
            <polygon points="{{ diagTopX }},0 700,0 700,{{ bannerH }} {{ diagBottomX }},{{ bannerH }}"></polygon>
          </clipPath>

          <clipPath id="shadowOnPhotoSide-{{ uid }}">
            <polygon points="{{ diagTopX }},0 700,0 700,{{ bannerH }} {{ diagBottomX }},{{ bannerH }}"></polygon>
          </clipPath>

          <filter id="sh_fold_soft-{{ uid }}" x="-260%" y="-260%" width="620%" height="620%">
            <feDropShadow dx="24" dy="1" stdDeviation="16" flood-color="#000" flood-opacity="0.14"/>
          </filter>

          <filter id="sh_fold_contact-{{ uid }}" x="-260%" y="-260%" width="620%" height="620%">
            <feDropShadow dx="10" dy="5" stdDeviation="4.2" flood-color="#000" flood-opacity="0.045"/>
          </filter>

          <filter id="sh_band_only-{{ uid }}" x="-260%" y="-260%" width="620%" height="620%">
            <feDropShadow in="SourceAlpha" dx="27" dy="17" stdDeviation="4.8" flood-color="#000" flood-opacity="0.22" result="ds1"/>
            <feDropShadow in="SourceAlpha" dx="52" dy="30" stdDeviation="26" flood-color="#000" flood-opacity="0.12" result="ds2"/>
            <feMerge>
              <feMergeNode in="ds1"/>
              <feMergeNode in="ds2"/>
            </feMerge>
          </filter>

          <linearGradient id="bandShine-{{ uid }}" x1="0" y1="0" x2="1" y2="0">
            <stop offset="0%" stop-color="#ffffff" stop-opacity="0.00"/>
            <stop offset="25%" stop-color="#ffffff" stop-opacity="0.22"/>
            <stop offset="50%" stop-color="#ffffff" stop-opacity="0.06"/>
            <stop offset="75%" stop-color="#ffffff" stop-opacity="0.18"/>
            <stop offset="100%" stop-color="#ffffff" stop-opacity="0.00"/>
          </linearGradient>

          <clipPath id="bandClip-{{ uid }}">
            <polygon points="{{ diagAtBandY }},{{ bandTopY }} {{ diagAtBandY | plus: bandW }},{{ bandTopY }} {{ diagBottomX | plus: bandW }},{{ bannerH }} {{ diagBottomX }},{{ bannerH }}"></polygon>
          </clipPath>
        </defs>

        <image xlink:href="{{ img_url }}" href="{{ img_url }}"
               x="0" y="0" width="700" height="{{ bannerH }}"
               clip-path="url(#imgClip-{{ uid }})"
               preserveAspectRatio="xMidYMid slice" />

        <polygon
          points="{{ diagAtBandY }},{{ bandTopY }} {{ diagAtBandY | plus: bandW }},{{ bandTopY }} {{ diagBottomX | plus: bandW }},{{ bannerH }} {{ diagBottomX }},{{ bannerH }}"
          fill="#000" filter="url(#sh_band_only-{{ uid }})"/>

        <polygon
          points="{{ diagAtBandY }},{{ bandTopY }} {{ diagAtBandY | plus: bandW }},{{ bandTopY }} {{ diagBottomX | plus: bandW }},{{ bannerH }} {{ diagBottomX }},{{ bannerH }}"
          fill="var(--bandColor)"/>

        <g clip-path="url(#bandClip-{{ uid }})" opacity="0.9">
          <rect x="0" y="0" width="700" height="{{ bannerH }}" fill="url(#bandShine-{{ uid }})"/>
        </g>

        <g clip-path="url(#shadowOnPhotoSide-{{ uid }})">
          <g filter="url(#sh_fold_soft-{{ uid }})">
            <polygon points="{{ diagTopX | minus: foldW }},0 {{ diagTopX }},0 {{ diagBottomX }},{{ bannerH }} {{ diagBottomX | minus: foldW }},{{ bannerH }}" fill="#fff"/>
          </g>
          <g filter="url(#sh_fold_contact-{{ uid }})">
            <polygon points="{{ diagTopX | minus: foldW }},0 {{ diagTopX }},0 {{ diagBottomX }},{{ bannerH }} {{ diagBottomX | minus: foldW }},{{ bannerH }}" fill="#fff"/>
          </g>
        </g>

        <polygon points="{{ diagTopX | minus: foldW }},0 {{ diagTopX }},0 {{ diagBottomX }},{{ bannerH }} {{ diagBottomX | minus: foldW }},{{ bannerH }}" fill="#fff"/>
        <polygon points="{{ diagTopX }},0 {{ diagTopX | plus: 2 }},0 {{ diagBottomX | plus: 2 }},{{ bannerH }} {{ diagBottomX }},{{ bannerH }}" fill="#000" opacity="0.06"/>
      </svg>

      <svg class="rt-svg-mobile" viewBox="0 0 700 260" preserveAspectRatio="xMidYMid slice" aria-hidden="true"
           xmlns="http://www.w3.org/2000/svg"
           xmlns:xlink="http://www.w3.org/1999/xlink">
        <image xlink:href="{{ img_url }}" href="{{ img_url }}"
               x="0" y="0" width="700" height="260"
               preserveAspectRatio="xMidYMid slice" />
      </svg>
    </div>
  </div>
</div>
{% endif %}
